sockets = 0;
channel = 0;
enum Net
{
    AllClients = -1,
    AllChannels = -1
}

var eventType = ds_map_find_value(async_load, "type");
if(eventType == network_type_connect)
{
    ds_list_add(sockets, ds_map_find_value(async_load, "socket"));
    ds_list_add(channel, 0);
    net_server_on_client_connect(ds_map_find_value(async_load, "socket"));
}
else if(eventType == network_type_disconnect)
{
    var _index = ds_list_find_index(sockets, ds_map_find_value(async_load, "socket"));
    ds_list_delete(sockets, _index);
    ds_list_delete(channel, _index);
    net_server_on_client_disconnect(ds_map_find_value(async_load, "socket"));
}
else if(eventType == network_type_data)
{
    net_server_recieve_packet(ds_map_find_value(async_load, "buffer"), ds_map_find_value(async_load, "id"));
}

