scripts.draw_lightning:
/// draw_lightning(x1, y1, x2, y2, xmin, xmax, ymin, ymax)
//                  0   1   2   3     4     5     6     7
// Draws a lightning between points.
/// @param {number} x1  source X
/// @param {number} y1  source Y
/// @param {number} x2  destination X
/// @param {number} y2  destination Y
/// @param {number} xmin  minimum distance step (>0)
/// @param {number} xmax  maximum distance step (>xmin)
/// @param {number} ymin  minimum "side" step (lightning "width")
/// @param {number} ymax  maximum "side" step (lightning "width")
/// @returns {int} number of segments drawn.
var i, r, c, l, dx, dy, sx, sy, px, py, cx, cy, alpha;
// avoid drawing outside view:
if (max(argument0, argument2) < view_xview[view_current] - 10) return 0;
if (max(argument1, argument3) < view_yview[view_current] - 10) return 0;
if (min(argument0, argument2) > view_xview[view_current] + view_wview[view_current] + 10) return 0;
if (min(argument1, argument3) > view_yview[view_current] + view_hview[view_current] + 10) return 0;
// find distance between points (used for loop)
l = point_distance(argument0, argument1, argument2, argument3);
if (l == 0) return 0;
// main direction:
i = point_direction(argument0, argument1, argument2, argument3);
dx = lengthdir_x(1, i); dy = lengthdir_y(1, i);
// side direction:
i += 90;
sx = lengthdir_x(1, i); sy = lengthdir_y(1, i);
// first point coordinates:
px = argument0; py = argument1;
c = 0;
i = random_range(argument4, argument5);
alpha = draw_get_alpha();
repeat (5000) { // edit for line segment limit
    r = choose(-1, +1) * (argument6 + (argument7 - argument6)
        * lengthdir_y(random(1), i / l * 180)); // this part makes lightning "wider" near middle
    // current point coordinates:
    if (i < l) {
        cx = argument0 + dx * i + sx * r;
        cy = argument1 + dy * i + sy * r;
    } else { cx = argument2; cy = argument3; } // end point
    // line drawing code here:
    // can be just a single draw_line or something fancy like this:
    draw_set_alpha(alpha * 0.3);
    draw_line_width(px, py, cx, cy, 3.7);
    draw_set_alpha(alpha * 0.7);
    draw_line_width(px, py, cx, cy, 1.3);
    // exit condition:
    if (i >= l) break
    // update previous point coordinates:
    px = cx; py = cy;
    // increments:
    c += 1;
    i += random_range(argument4, argument5);
}
draw_set_alpha(alpha);
return c

scripts.draw_sprite_3d:
///@desc drawSprite3DPersp(x,y,sprite, scale, hscale, rotation, perspective, alpha, HD)
///@arg x
///@arg y
///@arg sprite
///@arg scale
///@arg height_scale
///@arg rotation_angle
///@arg perspective_degrees
///@arg image_alpha
///@arg HD


//VERY messy and inefficient, probably better ways to do this

var _xx = argument0;
var _yy = argument1;
var _sprite = argument2;
var _scale = argument3;
var _heightScale = argument4;
var _imageAngle = argument5;
var _perspective = argument6;
var _alpha = argument7;

//Need to be calcualted every frame
var _perspectiveTop = dsin(_perspective);
var _perspectiveFront = dcos(_perspective);

// Getting the original 4 corners and angles for the corners from the origin
var _spriteOriginX = sprite_get_xoffset(_sprite)*_scale;
var _spriteOriginY = sprite_get_yoffset(_sprite)*_scale;
var _spriteWidth = sprite_get_width(_sprite)*_scale;
var _spriteHeight = sprite_get_height(_sprite)*_scale;

var _corner1Dist = point_distance(_spriteOriginX, _spriteOriginY, 0, 0);
var _corner2Dist = point_distance(_spriteOriginX, _spriteOriginY, _spriteWidth, 0);
var _corner3Dist = point_distance(_spriteOriginX, _spriteOriginY, _spriteWidth, _spriteHeight);
var _corner4Dist = point_distance(_spriteOriginX, _spriteOriginY, 0, _spriteHeight);

var _corner1Dir = point_direction(_spriteOriginX, _spriteOriginY, 0, 0);
var _corner2Dir = point_direction(_spriteOriginX, _spriteOriginY, _spriteWidth, 0);
var _corner3Dir = point_direction(_spriteOriginX, _spriteOriginY, _spriteWidth, _spriteHeight);
var _corner4Dir = point_direction(_spriteOriginX, _spriteOriginY, 0, _spriteHeight);

//////////////////////////////////////////////////////////////////////////
//Get new corner positions using the original 4 corners and angles

var _x1 = _xx + lengthdir_x(_corner1Dist, _corner1Dir + _imageAngle);
var _y1 = _yy + lengthdir_y(_corner1Dist * _perspectiveTop, _corner1Dir + _imageAngle);
var _x2 = _xx + lengthdir_x(_corner2Dist, _corner2Dir + _imageAngle);
var _y2 = _yy + lengthdir_y(_corner2Dist * _perspectiveTop, _corner2Dir + _imageAngle);
var _x3 = _xx + lengthdir_x(_corner3Dist, _corner3Dir + _imageAngle);
var _y3 = _yy + lengthdir_y(_corner3Dist * _perspectiveTop, _corner3Dir + _imageAngle);
var _x4 = _xx + lengthdir_x(_corner4Dist, _corner4Dir + _imageAngle);
var _y4 = _yy + lengthdir_y(_corner4Dist * _perspectiveTop, _corner4Dir + _imageAngle);

//Draw the sprites
if (argument8 == true){
	var _layerHeight = 0.5;
} else var _layerHeight = 1;

for (var _i = 0; _i < sprite_get_number(_sprite); _i+=_layerHeight){
	draw_sprite_pos(_sprite, floor(_i), 
					_x1, _y1-_i*_heightScale*_perspectiveFront,
					_x2, _y2-_i*_heightScale*_perspectiveFront, 
					_x3, _y3-_i*_heightScale*_perspectiveFront, 
					_x4, _y4-_i*_heightScale*_perspectiveFront,
					_alpha);
}

scripts.exact_gauss:
/* 
**  Usage: 
**      exact_gauss(mean, deviation) 
** 
**  Arguments: 
**      mean        mean value of the distribution 
**      deviation   standard deviation of 
distribution 
** 
**  Returns: 
**      a pseudo-random number with an exact Gaussian
distribution 
** 
**  Notes: 
**  See 
http://en.wikipedia.org/wiki/Normal_distribution 
**      for more information about Gaussian 
distributions 
** 
**  GMLscripts.com 
*/ 
{ 
    var x1, x2, w; 

    do { 
        x1 = random(2) - 1; 
        x2 = random(2) - 1; 
        w = x1*x1 + x2*x2; 
    } until (0 < w && w < 1); 

    w = sqrt(-2 * ln(w)/w); 
    return argument0 + argument1 * x1 * w; 
}

scripts.FlowField_move:
//adapt with terrain collision scripts

var grid = obj_flowfield.grid;
var gridSize = obj_flowfield.gridSize;
var targetNode = obj_flowfield.targetNode;
var xx = x div gridSize;
var yy = y div gridSize;

//these two are the most important ones
var currentNode = ds_grid_get(grid, xx, yy);
var parentNode = currentNode.parent;

//everyhing below here is so we get our thing centered on the grid

if (currentNode == targetNode) //if the thing reaches its goal, move it to the center
{
    var xx = currentNode.x * gridSize + gridSize/2;
    var yy = currentNode.y * gridSize + gridSize/2;
    if (distance_to_point(xx,yy) < 0.1)
    {
        spd = 0;    
    }   
}
else if (parentNode != undefined) //if it hasn't reached the goal, move it along the middle of the grid
{
    var x1 = currentNode.x * gridSize + gridSize/2;
    var y1 = currentNode.y * gridSize + gridSize/2;
    var x2 = parentNode.x * gridSize + gridSize/2;
    var y2 = parentNode.y * gridSize + gridSize/2;

    spd = 4;
    if (distance_to_point(x1,y1) < 0.1)
    {
        dir = point_direction(x1,y1,x2,y2);   
    }
}
else //the goal is unreachable
{
    spd = 0;
}

//move it in the direction of the flowfield
x += lengthdir_x(spd, dir);
y += lengthdir_y(spd, dir);

