scripts.image_stream_add_files:
///image_stream_add_files(group,identifier,basename,xorig,yorig) - creates a sprite from a list of files with the specified name (spr_player_0,spr_player_1,...etc)
var _l = global.m_ex_image[? argument0 ];

// Error checking
if( ds_list_size( _l ) != 3 ){
    show_error( "Image stream not started " + chr(13) + "Group: " + string( argument0 ) + chr(13) + "Identifier " + string( argument1 ), true );
    return false; 
}

var _m = _l[| 2 ];
var _p_sprite = _m[? "sprite" ];
var _removeback = _m[? "removeback" ];

var _pq = ds_priority_create();
var _load_data = ds_list_create();

// Scan the file system
var _subimg_n = 0;
var _path_sprite =  argument2 + "_";
var _spritename = filename_name( _path_sprite );

var _bbox_left = 500000;
var _bbox_top = 500000;
var _bbox_right = -500000;
var _bbox_bottom = -500000;

var _file = file_find_first( _path_sprite + "*", 0 );
while( _file != "" ){
    var _file_ext = filename_ext( _file );
    var _file_extl = string_lower( _file_ext );

    // Make sure it is an image file
    if( _file_extl == ".png" || _file_extl == ".jpg" || _file_extl == ".jpeg" || _file_extl == ".gif" ){
        var _file_name = filename_name( _file );
        var _stripped_name = string_replace( string_replace( _file_name, _spritename, "" ), _file_ext, "" );

        // Make sure that it's coin_0.png and not coin_test_0.png
        if( string_digits( _stripped_name ) == _stripped_name && string_length( _stripped_name ) ){ 
            var _sub = real( _stripped_name );
            var _spr = sprite_add( _file, 1, _removeback, false, 0, 0 );
            //var _spr = sprite_add_ns( _file, 1, _removeback, false, 0, 0 );
            _bbox_left = min( sprite_get_bbox_left( _spr ), _bbox_left );
            _bbox_top = min( sprite_get_bbox_top( _spr ), _bbox_top );
            _bbox_right = max( sprite_get_bbox_right( _spr ), _bbox_right );
            _bbox_bottom = max( sprite_get_bbox_bottom( _spr ), _bbox_bottom );

            ds_priority_add( _pq, _spr, _sub );
        }
    }

    _file = file_find_next();
}
file_find_close();

if( ds_priority_size( _pq ) ){
    var _spr = ds_priority_find_min( _pq );

    if( sprite_get_width( _spr ) <= _m[? "w" ] + _m[? "sep" ] && sprite_get_height( _spr ) <= _m[? "h" ] + _m[? "sep" ] ){
        _load_data[| __IS_STREAM_IMAGE.ID ] = string( argument1 );
        _load_data[| __IS_STREAM_IMAGE.TYPE ] = __IS.TYPE_LIST;
        _load_data[| __IS_STREAM_IMAGE.FPATH ] = argument2;
        _load_data[| __IS_STREAM_IMAGE.SPRITES ] = _pq;
        _load_data[| __IS_STREAM_IMAGE.SUBIMG_COUNT ] = ds_priority_size( _pq );

        _load_data[| __IS_STREAM_IMAGE.XORIG ] = argument3 * sprite_get_width( _spr );
        _load_data[| __IS_STREAM_IMAGE.YORIG ] = argument4 * sprite_get_height( _spr );

        if( _m[? "clamp" ] == false ){
            _load_data[| __IS_STREAM_IMAGE.CLAMP_LEFT ] = 0;
            _load_data[| __IS_STREAM_IMAGE.CLAMP_TOP ] = 0;
            _load_data[| __IS_STREAM_IMAGE.WIDTH ] = sprite_get_width( _spr );
            _load_data[| __IS_STREAM_IMAGE.HEIGHT ] = sprite_get_height( _spr );
        } else {
            _load_data[| __IS_STREAM_IMAGE.CLAMP_LEFT ] = _bbox_left;
            _load_data[| __IS_STREAM_IMAGE.CLAMP_TOP ] = _bbox_top;
            _load_data[| __IS_STREAM_IMAGE.WIDTH ] = _bbox_right - _bbox_left + 1;
            _load_data[| __IS_STREAM_IMAGE.HEIGHT ] = _bbox_bottom - _bbox_top + 1;
        }

        var _priority = floor( ( _load_data[| __IS_STREAM_IMAGE.WIDTH ] + _load_data[| __IS_STREAM_IMAGE.HEIGHT ] ) * 0.5 );

    } else {
        while( ds_priority_size( _pq ) ){
            sprite_delete( ds_priority_delete_min( _pq ) );
        }
        ds_list_destroy( _load_data );
        show_error( "Image is larger than texturepage! " + chr(13) + "Group: " + string( argument0 ) + chr(13) + "Identifier " + string( argument1 ), false );
        return false;
    }
} else {
    ds_priority_destroy( _pq );
    ds_list_destroy( _load_data );

    show_error( "Could not find subimage files from '" + string( argument2 ) + "' for identifier '" + string( argument1 ) + " in group " + string( argument0 ), false );
    return false;
}

ds_priority_add( _p_sprite, _load_data, _priority );
return true;

scripts.image_stream_add_sheet:
#define image_stream_add_sheet
///image_stream_add_sheet(group,identifier,fname,hor_count,ver_count,xorig,yorig)
var _l = global.m_ex_image[? argument0 ];

// Error checking
if( ds_list_size( _l ) != 3 ){
    show_error( "Image stream not started " + chr(13) + "Group: " + string( argument0 ) + chr(13) + "Identifier " + string( argument1 ), true );
    return false; 
}

var _m = _l[| 2 ];
var _p_sprite = _m[? "sprite" ];

var _bck = background_add( argument2, _m[? "removeback" ], false );
var _spr_w = background_get_width( _bck ) / argument3;
var _spr_h = background_get_height( _bck ) / argument4;
var _priority = floor( ( _spr_w + _spr_h ) * 0.5 );

var _load_data = ds_list_create();
_load_data[| __IS_STREAM_IMAGE.ID ] = string( argument1 );
_load_data[| __IS_STREAM_IMAGE.TYPE ] = __IS.TYPE_SHEET;
_load_data[| __IS_STREAM_IMAGE.FPATH ] = argument2;
_load_data[| __IS_STREAM_IMAGE.SUBIMG_COUNT ] = argument3 * argument4;
_load_data[| __IS_STREAM_IMAGE.SUBIMG_ROWS ] = argument4;
_load_data[| __IS_STREAM_IMAGE.XORIG ] = argument5;
_load_data[| __IS_STREAM_IMAGE.YORIG ] = argument6;

if( _priority <= 1 and !file_exists( argument2 ) ){
    _load_data[| __IS_STREAM_IMAGE.SPRITES ] = _bck;

    var _l_loading = _m[? "loading" ];
    ds_list_add( _l_loading, _load_data );
    _m[? "finished" ] = false;
} else {
    if( _spr_w <= _m[? "w" ] + _m[? "sep" ] && _spr_h <= _m[? "h" ] + _m[? "sep" ] ){
        // The image came from a file, finish everything
        _load_data[| __IS_STREAM_IMAGE.SPRITES ] = _bck;
        __isa_sheet_bake( _load_data, _m[? "clamp" ] );
        _priority = floor( ( _load_data[| __IS_STREAM_IMAGE.WIDTH ] + _load_data[| __IS_STREAM_IMAGE.HEIGHT ] ) * 0.5 );
    } else {
        background_delete( _bck );
        ds_list_destroy( _load_data );
        show_error( "Image is larger than texturepage! " + chr(13) + "Group: " + string( argument0 ) + chr(13) + "Identifier " + string( argument1 ), false );
        return false;
    }

}

ds_priority_add( _p_sprite, _load_data, _priority );
return true;

#define __isa_sheet_bake
///__isa_sheet_bake(load_data, clamp)

var _load_data = argument0;

var _bck = _load_data[| __IS_STREAM_IMAGE.SPRITES ];


var _subimg_ver = _load_data[| __IS_STREAM_IMAGE.SUBIMG_ROWS ];
var _subimg_hor = _load_data[| __IS_STREAM_IMAGE.SUBIMG_COUNT ] / _subimg_ver;

var _spr_w_raw = background_get_width( _bck ) / _subimg_hor;
var _spr_h_raw = background_get_height( _bck ) / _subimg_ver;
var _spr_w = floor( _spr_w_raw );
var _spr_h = floor( _spr_h_raw );
_load_data[| __IS_STREAM_IMAGE.XORIG ] *= _spr_w;
_load_data[| __IS_STREAM_IMAGE.YORIG ] *= _spr_h;


// Make sure that the user didn't enter the wrong subimage count
if( _spr_w_raw != _spr_w ){
    __is_log( "IMAGE STREAM WARNING: Image '" + string( _load_data[| __IS_STREAM_IMAGE.ID ] ) + 
        "' may have wrong amount of subimages per row. Width " + string( background_get_width( _bck ) ) + " / " + string( _subimg_hor ) + " = " + string( _spr_w_raw ) );
}
if( _spr_h_raw != _spr_h ){
    __is_log( "IMAGE STREAM WARNING: Image '" + string( _load_data[| __IS_STREAM_IMAGE.ID ] ) + 
        "' may have wrong amount of subimages per column. Height " + string( background_get_height( _bck ) ) + " / " + string( _subimg_ver ) + " = " + string( _spr_h_raw ) );
}
// Bake into sprite

var _surf = surface_create( background_get_width( _bck ), background_get_height( _bck ) );
surface_set_target( _surf );
draw_clear_alpha( c_black, 0 );
draw_background( _bck, 0, 0 );
var _spr = sprite_create_from_surface( _surf, 
    0, 0, 
    _spr_w, _spr_h, 
    false, false, 
    0, 0 );
var i = 1; // i = x + width * y
repeat( _subimg_hor * _subimg_ver - 1 ){
    var _x = i mod _subimg_hor;
    var _y = i div _subimg_hor;

    sprite_add_from_surface( _spr, _surf, _x * _spr_w, _y * _spr_h, _spr_w, _spr_h, false, false );
    i++;
}
surface_reset_target();
surface_free( _surf);
background_delete( _bck );

if( argument1 == false ){
    _load_data[| __IS_STREAM_IMAGE.CLAMP_LEFT ] = 0;
    _load_data[| __IS_STREAM_IMAGE.CLAMP_TOP ] = 0;
    _load_data[| __IS_STREAM_IMAGE.WIDTH ] = _spr_w;
    _load_data[| __IS_STREAM_IMAGE.HEIGHT ] = _spr_h;
} else {
    _load_data[| __IS_STREAM_IMAGE.CLAMP_LEFT ] = sprite_get_bbox_left( _spr );
    _load_data[| __IS_STREAM_IMAGE.CLAMP_TOP ] = sprite_get_bbox_top( _spr );
    _load_data[| __IS_STREAM_IMAGE.WIDTH ] = sprite_get_bbox_right( _spr ) - sprite_get_bbox_left( _spr ) + 1;
    _load_data[| __IS_STREAM_IMAGE.HEIGHT ] = sprite_get_bbox_bottom( _spr ) - sprite_get_bbox_top( _spr ) + 1;
}

_load_data[| __IS_STREAM_IMAGE.SPRITES ] = _spr;

scripts.image_stream_finish:
#define image_stream_finish
///image_stream_finish(group)
if( !image_stream_is_received( string( argument0 ) ) ){
    show_error( "The image stream has not finished yet " + chr(13) + "Group: " + string( argument0 ), true );
    return false;
}

enum __IS_FINISH {
    STREAM,
    TEXPAGES,
    AREAS,
    IMG_GRID,
    IMG_GRID_POS,
    IMG_DATA,
    IMG_SUBIMG,
    CLAMP,
    IMG_WIDTH,
    IMG_HEIGHT
}

// Stream data
var _l            = global.m_ex_image[? string( argument0 ) ];
var _l_image      = _l[| 0 ];
var _l_background = _l[| 1 ];
var _m_stream     = _l[| 2 ];

// Stream settings
var _clamp = _m_stream[? "clamp" ];
var _p_sprite    = _m_stream[? "sprite" ];
var _p_sprite_3d = _m_stream[? "sprite_3d" ];
var _width     = _m_stream[? "w" ];
var _height    = _m_stream[? "h" ];
var _sep       = _m_stream[? "sep" ];

// Draw settings
var _begin_alpha  = draw_get_alpha();
var _begin_colour = draw_get_colour();
draw_set_alpha( 1.0 );
draw_set_colour( c_white );
draw_enable_alphablend( false );

// CREATE THE DATA STRUCTURES NECESSARY FOR ADDING THE SPRITES ON THE TEXTURE PAGE
var _l_areas = ds_list_create();
var _q_trash = ds_queue_create();
var _l_texpage = ds_list_create();

// Session
var _session;
_session[ __IS_FINISH.STREAM ]   = _m_stream;
_session[ __IS_FINISH.TEXPAGES ] = _l_texpage;
_session[ __IS_FINISH.AREAS ]    = _l_areas;
_session[ __IS_FINISH.CLAMP ]    = _clamp;

__isf_texpage_create( _session );

while( ds_priority_size( _p_sprite ) ){ // LOOP THROUGH THE SPRITES AND ADD THEM TO THE TEXTURE PAGE WHERE POSSIBLE
    var _l_img_data = ds_priority_delete_max( _p_sprite );
    var _image_drawn = false;
    var _image_maindata_added = false;

    var _spr_number = _l_img_data[| __IS_STREAM_IMAGE.SUBIMG_COUNT ];
    var _g_image = ds_grid_create( __ISG_IMG.COUNT + _spr_number * __ISG_SUBIMG.COUNT + 1, 1 );
    ds_list_add( _l_image, _g_image );
    _session[ __IS_FINISH.IMG_GRID ] = _g_image;
    _session[ __IS_FINISH.IMG_GRID_POS ] = 0;
    _session[ __IS_FINISH.IMG_DATA ] = _l_img_data;
    _session[ __IS_FINISH.IMG_SUBIMG ] = 0;

    //show_debug_message( "Finishing " + string( _l_img_data[| __IS_STREAM_IMAGE.ID ] ) );

    switch( _l_img_data[| __IS_STREAM_IMAGE.TYPE ] ){
        case __IS.TYPE_LIST:
            var _p_image = _l_img_data[| __IS_STREAM_IMAGE.SPRITES ];

            while( ds_priority_size( _p_image ) ){
                var _subimg = ds_priority_delete_min( _p_image );

                var _min_area_id = __isf_find_area( _session, _l_img_data );
                if( _min_area_id == -1 ){ // Couldn't find an area for the subimage, no room on the texpage
                    __isf_texpage_create( _session );
                    _min_area_id = __isf_find_area( _session, _l_img_data );
                }

                __isf_subimg_to_area( _session, _subimg, 0, _min_area_id );

                ds_queue_enqueue( _q_trash, _subimg );
            }
            ds_list_destroy( _l_img_data );
        break;

        case __IS.TYPE_STRIP:
            var _spr = _l_img_data[| __IS_STREAM_IMAGE.SPRITES ];
            var _spr_number = sprite_get_number( _spr );

            for( var i = 0; i < sprite_get_number( _spr ); i++ ){
                var _min_area_id = __isf_find_area( _session, _l_img_data );
                if( _min_area_id == -1 ){ // Couldn't find an area for the subimage, no room on the texpage
                    __isf_texpage_create( _session );
                    _min_area_id = __isf_find_area( _session, _l_img_data );
                }

                __isf_subimg_to_area( _session, _spr, i, _min_area_id );
            }
            ds_queue_enqueue( _q_trash, _spr );
            ds_list_destroy( _l_img_data );
        break;

        case __IS.TYPE_SHEET:
            var _spr = _l_img_data[| __IS_STREAM_IMAGE.SPRITES ];
            var _spr_number = sprite_get_number( _spr );

            for( var i = 0; i < sprite_get_number( _spr ); i++ ){
                var _min_area_id = __isf_find_area( _session, _l_img_data );
                if( _min_area_id == -1 ){ // Couldn't find an area for the subimage, no room on the texpage
                    __isf_texpage_create( _session );
                    _min_area_id = __isf_find_area( _session, _l_img_data );
                }

                __isf_subimg_to_area( _session, _spr, i, _min_area_id );
            }
            ds_queue_enqueue( _q_trash, _spr );
            ds_list_destroy( _l_img_data );
        break;

        default:
            show_error( "Unknown image type found for " + _l_img_data[| __IS_STREAM_IMAGE.ID ] + " in group " + argument0, false );
        break;
    }
}
surface_reset_target();

// Clear memory
while( ds_queue_size( _q_trash ) > 0 ){
    sprite_delete( ds_queue_dequeue( _q_trash ) );
}
// CREATE THE BACKGROUND (TEXTUREPAGE)
for( var n = 0; n < ds_list_size( _l_texpage ); n += 2 ){
    var _back_temp = background_create_from_surface( _l_texpage[| n ], 0, 0, surface_get_width( _l_texpage[| n ] ), surface_get_height( _l_texpage[| n ] ), false, false );
    background_assign( _l_texpage[| n + 1 ], _back_temp );
    ds_list_add( _l_background, _l_texpage[| n + 1 ] );
    background_delete( _back_temp );
    surface_free( _l_texpage[| n ] );
}


// 3D specific images.
while( ds_priority_size( _p_sprite_3d ) > 0 ){
    var _l_img      = ds_priority_delete_max( _p_sprite_3d );
    var _spr        = _l_img[| __IS_STREAM_IMAGE.SPRITES ];
    var _identifier = _l_img[| __IS_STREAM_IMAGE.ID ];
    var _subimg     = sprite_get_number( _spr );
    var _xorig      = _l_img[| __IS_STREAM_IMAGE.XORIG ];
    var _yorig      = _l_img[| __IS_STREAM_IMAGE.YORIG ];
    var _w          = sprite_get_width( _spr );
    var _surface    = surface_create( _w, sprite_get_height( _spr ) );

    var _g_image = ds_grid_create( __ISG_IMG.COUNT + _subimg * __ISG_SUBIMG.COUNT + 1, 1 );
    ds_list_add( _l_image, _g_image );
    var _pos = 0;
    _g_image[# __ISG_IMG.ID, 0 ] = _identifier;                    // IDENTIFIER
    _g_image[# __ISG_IMG.SUBIMAGES, 0 ] = _subimg;                        // SUBIMAGE
    _g_image[# __ISG_IMG.WIDTH, 0 ] = _w;                             // SUBIMAGE WIDTH
    _g_image[# __ISG_IMG.HEIGHT, 0 ] = sprite_get_height( _spr );      // SUBIMAGE HEIGHT
    _g_image[# __ISG_IMG.XORIGIN, 0 ] = _xorig;                         // XORIGIN
    _g_image[# __ISG_IMG.YORIGIN, 0 ] = _yorig;                         // YORIGIN

    _g_image[# __ISG_IMG.BBOX_LEFT, 0 ]   = sprite_get_bbox_left( _spr );
    _g_image[# __ISG_IMG.BBOX_TOP, 0 ]    = sprite_get_bbox_top( _spr );
    _g_image[# __ISG_IMG.BBOX_RIGHT, 0 ]  = sprite_get_bbox_right( _spr );
    _g_image[# __ISG_IMG.BBOX_BOTTOM, 0 ] = sprite_get_bbox_bottom( _spr );

    _pos += __ISG_IMG.COUNT;

    for( var n = 0; n < _subimg; n++ ){
        surface_set_target( _surface );
        draw_clear_alpha( 0, 0 );
        draw_sprite_part( _spr, n, 0, 0, n * _w + _w, sprite_get_height( _spr ), 0, 0 );
        surface_reset_target();
        var _back_subimg = background_create_from_surface( _surface, 0, 0, _w, sprite_get_height( _spr ), false, false );
        ds_list_add( _l_background, _back_subimg );
        _g_image[# _pos + __ISG_SUBIMG.BACK, 0 ] = _back_subimg; // BACKGROUND
        _g_image[# _pos + __ISG_SUBIMG.X, 0 ] = 0;            // X
        _g_image[# _pos + __ISG_SUBIMG.Y, 0 ] = 0;            // Y
        _pos += __ISG_SUBIMG.COUNT;
    }
    _g_image[# ds_grid_width( _g_image ) - 1, 0 ] = _l_img[| __IS_STREAM_IMAGE.FPATH ]; // FNAME

    surface_free( _surface );
    sprite_delete( _spr );
    ds_list_destroy( _l_img );
}
draw_enable_alphablend( true );

draw_set_alpha( _begin_alpha );
draw_set_colour( _begin_colour );

// Clear memory
ds_list_destroy( _l_areas );
ds_priority_destroy( _p_sprite );
ds_priority_destroy( _p_sprite_3d );
ds_list_destroy( _m_stream[? "loading" ] );
ds_queue_destroy( _q_trash );
ds_list_destroy( _l_texpage );    
ds_list_delete( global.m_ex_image[? string( argument0 ) ], 2 );

return true;

#define __isf_find_area
///__isf_find_area(session,image_data)
var _l_areas = argument0[ __IS_FINISH.AREAS ];
var _min_area_size = $10000000000000;
var _min_area_id   = -1;
var _w = argument1[| __IS_STREAM_IMAGE.WIDTH ];
var _h = argument1[| __IS_STREAM_IMAGE.HEIGHT ];


for( var n = 0; n < ds_list_size( _l_areas ); n += 4 ){
    if( _w <= _l_areas[| n + 2 ] and _h <= _l_areas[| n + 3 ] ){
        if( ( ( _l_areas[| n + 2 ] + _l_areas[| n + 3 ] ) / 2 ) < _min_area_size ){
            _min_area_size = ( _l_areas[| n + 2 ] + _l_areas[| n + 3 ] ) / 2;
            _min_area_id = n;
        }
    }
}

return _min_area_id;

#define __isf_texpage_create
///__isf_texpage_create(session)

