scripts.net_packet_send:
#define net_packet_send
///net_packet_send([target])
/*
 * Sends the created packet to the given target. Only the server needs to specify the
 * target. The client will always send the packet to the server.
 *
 * [target]: The client socket to send the packet to. (Use Net.AllClients for all clients
 *           and Net.RandomClient for a random client)
 *
 * Returns: true if the sending was successful, false otherwise
*/

if(!net_is_server() && !net_is_client())
{
    show_error("Cannot send packet. Reason: Server or Client does not exist", false);
    return false;
}
if(net_is_server())
{
    with(obj_server)
    {
        net_packet_construct_buffer();
        //If we are handling all clients
        if(argument[0] == Net.AllClients)
        {
            //Loop through all clients and send the packet to them
            for(var i = 0; i < ds_list_size(sockets); i ++)
            {
                //network_send_udp(server, "127.0.0.1", 7070, buffer, buffer_tell(buffer));
                network_send_packet(sockets[| i], buffer, buffer_tell(buffer));
            }
        }
        //Client specified
        else
        {
            //network_send_udp(argument[0], "127.0.0.1", 7070, buffer, buffer_tell(buffer));
            network_send_packet(argument[0], buffer, buffer_tell(buffer));
        }
    }
    return true;
}
if(net_is_client())
{
    with(obj_client)
    {
        buffer_seek(buffer, buffer_seek_start, 0);
        buffer_write(buffer, buffer_string, obj_packet_controller.packetPrefix);
        while(!ds_queue_empty(obj_packet_controller.dsBuffer))
        {
            buffer_write(buffer, ds_queue_dequeue(obj_packet_controller.dsBufferType), ds_queue_dequeue(obj_packet_controller.dsBuffer));
        }
        //network_send_udp(client, "127.0.0.1", 7070, buffer, buffer_tell(buffer));
        network_send_packet(client, buffer, buffer_tell(buffer));
    }
}
return true;

#define net_packet_construct_buffer
///net_packet_construct_buffer()
buffer_seek(buffer, buffer_seek_start, 0);
buffer_write(buffer, buffer_string, obj_packet_controller.packetPrefix);
while(!ds_queue_empty(obj_packet_controller.dsBuffer))
{
    buffer_write(buffer, ds_queue_dequeue(obj_packet_controller.dsBufferType), ds_queue_dequeue(obj_packet_controller.dsBuffer));
}

scripts.net_packet_send_channel:
///net_packet_send_channel(channel, target, [target2], [target3], ...)
/*
 * SERVER ONLY
 *
 * Sends a packet to the target, if it is on that channel
 *
 * channel: The channel that the targets must be on to be able to get the packet.
 *          Can be Net.AllChannels for all channels, or use net_packet_send for 
 *          all channels
 * target:  The target to send to, can be Net.AllClients to send to all clients
 *          on the channel.
 *
 * Returns: true if the sending succeeded, false otherwise.
*/
if(net_is_client())
    return net_packet_send();
if(argument[1] == Net.AllClients)
{
    if(argument[0] == Net.AllChannels)
    {
        return net_packet_send(Net.AllClients);
    }
    else
    {
        with(server)
        {
            net_packet_construct_buffer();
            var ret = true;
            for(var i = 0; i < ds_list_size(sockets); i ++)
            {
                var _socket = sockets[| i];
                var _channel = net_get_channel(_socket);
                if(_channel == argument[0])
                {
                    if(network_send_packet(_socket, buffer, buffer_tell(buffer)) < 0)
                        ret = false;
                }
            }
            return ret;
        }        
    }
}
else
{
    var _channel = net_get_channel(argument[1]);
    if(_channel == argument[0] || argument[0] == Net.AllChannels)
    {
        return net_packet_send(argument[1]);
    }
    return false;
}

scripts.net_server_create:
///net_server_create(port, maxClients)
/*
 * Creates a server. Run this script once to create a new server.
 *
 * port:       The port to use (must be forwarded).
 * maxClients: The maximum number of clients that can be connected.
 *
 * Returns: true if the creation succeeded, false otherwise
*/
//Don't create two servers in the same program
if(net_is_server())
{
    show_error("Could not create server. Reason: Server has already been created.", false);
    return false;
}
if(net_is_client())
{
    show_error("Could not create server. Reason: Client has already been created.", false);
    return false;
}
//Read arguments
var port = argument0, maxClients = argument1;
//Create server object
var server = instance_create(0, 0, obj_server);
//Create server
server.server = network_create_server(network_socket_tcp, port, maxClients);
if(server.server < 0)
{
    with(server)
        instance_destroy();
    show_error("Could not create server. Reason: Unknown. Port is probably occupied", false);
    return false;
}
//Create buffer
server.buffer = buffer_create(2048, buffer_grow, 1);
//Create socket list
server.sockets = ds_list_create();
//Create channel list
server.channel = ds_list_create();
return true;

scripts.net_server_destroy:
///net_server_destroy([message])
/*
 * Destroys the network socket. This will disconnect all clients, but will send a
 * packet containing information about the disconnection.
 *
 * [message]: The message to send to the clients. If left out, the message will be
 *            "Server has shut down".
 *
 * Returns: None
*/

if(net_is_server())
{
    //Set the message
    var message = "Server has shut down";
    if(argument_count > 0)
        message = argument[0];

    //Create the shutdown package
    net_packet_create("Shutdown");
    net_packet_add(message);
    net_packet_send(Net.AllClients);

    //Remove the server
    with(obj_server)
    {
        network_destroy(server);
        buffer_delete(buffer);
        ds_list_destroy(sockets);
        ds_list_destroy(channel);
        instance_destroy();
    }
    with(obj_packet_controller)
    {
        instance_destroy();
    }
}

scripts.net_server_disconnect_client:
///net_server_disconnect_client(client, [message])
/*
 * Disconnects the given client. Net.AllClients and Net.RandomClient can both be used.
 *
 * client:    The client to disconnect from the server
 * [message]: The message to send to the client. If left out, the client will not show
 *            any message.
 *
 * Returns: None
*/

if(net_is_server())
{
    //Set the message
    var message = "";
    if(argument_count > 1)
        message = argument[1];

    //Create shutdown packet
    net_packet_create("Shutdown");
    net_packet_add(message);
    net_packet_send(argument[0]);
}

scripts.net_server_recieve_packet:
///net_server_recieve_packet(buffer, clientSocket)
/*
 * This script is called by the obj_server when the server recieves a packet.
 *
 * buffer:       The buffer that the server recieved.
 * clientSocket: The socket that sent the packet.
 *
 * Returns: none
*/
//Get the data that was send
var netBuffer = argument0;
//Get the client who sent it
var clientSocket = argument1;
//What will this packet contain?
