room_test.code:
var input = -1;
while(input != 0 && input != 1)
{
    input = get_integer("Server: 0, Client: 1", 0);
}
if(input == 0)
{
    while(!net_server_create(get_integer("Port", 7070), get_integer("Max Clients", 4)))
    {
        if(get_integer("Try to create a server again? (1/0)", 1) == 0)
        {
            game_end();
            exit;
        }
    }
}
else if(input == 1)
{
    while(!net_client_create(get_string("IP", "127.0.0.1"), get_integer("Port", 7070)))
    {
        if(get_integer("Try to connect again? (1/0)", 1) == 0)
        {
            game_end();
            exit;
        }
    }
}

